import fs3 from "node:fs";
import os4 from "node:os";
import path2 from "node:path";
function lairHome() {
  if (process.env.LAIR_HOME) return path2.resolve(process.env.LAIR_HOME);
  if (process.env.XDG_DATA_HOME) return path2.join(process.env.XDG_DATA_HOME, "lair");
  return path2.join(os4.homedir(), ".local", "share", "lair");
}
function readTrimmed(file) {
  try {
    return fs3.readFileSync(file, "utf8").trim();
  } catch {
    return "";
  }
}
async function connect() {
  const run = path2.join(lairHome(), "run");
  const url = readTrimmed(path2.join(run, "desktop.url")) || "http://127.0.0.1:9797";
  const token = readTrimmed(path2.join(run, "desktop.token"));
  if (!token) {
    throw new Error("Daemon no disponible; inicia Lair con `lair daemon --foreground`.");
  }
  return new HttpDaemonClient(url, token);
}

